import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Package, Truck, CheckCircle } from 'lucide-react';
import './Dashboard.css';

const Dashboard = () => {
    const [bookings, setBookings] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchBookings = async () => {
            try {
                const res = await axios.get("http://localhost:9023/api/parcels/all");
                console.log("Backend Se Ye Data Aa Raha Hai:", res.data); // Inspect -> Console mein check karo
                setBookings(res.data);
            } catch (err) {
                console.error("Error fetching data:", err);
            } finally {
                setLoading(false);
            }
        };
        fetchBookings();
    }, []);

    return (
        <div className="dashboard-wrapper">
            <div className="dashboard-content">
                <header className="db-header">
                    <h2>Welcome back, <span className="gold-text">Aarti</span> 👋</h2>
                    <p>SafeParcel Management Dashboard</p>
                </header>

                <div className="table-section">
                    <div className="table-header">
                        <h3>All Deliveries</h3>
                    </div>
                    <div className="table-container">
                        <table>
                            <thead>
                                <tr>
                                    <th>Id</th>
                                    <th>Tracking Id</th>
                                    <th>Customer</th>
                                    <th>From-To</th>
                                    <th>Vehicle</th>
                                    <th>Status</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr><td colSpan="7" className="text-center">Loading...</td></tr>
                                ) : bookings.length > 0 ? (
                                    bookings.map((order, index) => {
                                        // Yahan hum data ko manually fix kar rahe hain
                                        const id = order.id || index + 1;
                                        const trackId = order.trackingId || "N/A";
                                        const name = order.userName || order.customerName || "Customer";
                                        const route = `${order.sourceAddress || 'N/A'} → ${order.destinationAddress || 'N/A'}`;
                                        const vehicle = order.vehicleType || "Bike";
                                        const status = order.status || "DELIVERED";

                                        return (
                                            <tr key={trackId + index}>
                                                <td>{id}</td>
                                                <td><strong>{trackId}</strong></td>
                                                <td>{name}</td>
                                                <td>{route}</td>
                                                <td>{vehicle}</td>
                                                <td>
                                                    <span className={`status-tag ${status.toLowerCase()}`}>
                                                        {status}
                                                    </span>
                                                </td>
                                                <td>
                                                    <button className="manage-btn">Update</button>
                                                </td>
                                            </tr>
                                        );
                                    })
                                ) : (
                                    <tr><td colSpan="7" className="text-center">No Data Found</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
